'use strict';
const DATA=window.WORKSHOP;
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,label,cls='')=>`<a class="${cls}" href="${escapeHTML(url)}" target="_blank" rel="noopener">${escapeHTML(label)} →</a>`;
const source=(index,page,label='Instrukcja źródłowa')=>external(DATA.pdf_guides[index].file+'#page='+page,`${label} · s. ${page}`);
const cite=(i,p,label)=>`<p class="source-line">${source(i,p,label)}</p>`;
const figure=(file,title,i,page,caption='',portrait=false)=>`<figure class="image-card${portrait?' portrait':''}"><button type="button" data-zoom="assets/przewodnik/${file}" data-title="${escapeHTML(title)}" data-caption="${escapeHTML(DATA.pdf_guides[i].title+' · strona '+page+'. '+caption)}" aria-label="Powiększ: ${escapeHTML(title)}"><img src="assets/przewodnik/${file}" alt="${escapeHTML(title)}" loading="eager" decoding="async"></button><span class="zoom-label" aria-hidden="true">Powiększ ekran →</span><figcaption><strong>${escapeHTML(title)}.</strong> ${escapeHTML(caption)} ${source(i,page,'Oryginał PDF')}</figcaption></figure>`;
const steps=items=>`<ol class="steps">${items.map(([title,text])=>`<li><strong>${title}</strong>${text}</li>`).join('')}</ol>`;
const chapter=(id,n,title,lead,body)=>`<section class="chapter" id="${id}"><header class="chapter-heading"><span class="chapter-number">${n}</span><div><h2>${title}</h2><p>${lead}</p></div></header>${body}</section>`;
const detail=(title,body)=>`<details><summary>${title}</summary><div class="detail-body">${body}</div></details>`;
const currentHelp=(url,label)=>`<p class="source-line">${external(url,label+' — pomoc ZPE sprawdzona 3.11.2026')}</p>`;
const olderProcedure='<p class="notice"><strong>Opis ze starszego PDF-u.</strong> To dokumentacja innej wersji interfejsu. Nie potwierdzono tych przycisków i ustawień na obecnym koncie szkolnym. Dla kursów stosuj rozdział „Udostępnianie i wyniki”.</p>';
const SOURCE_STATUS=[
 'Zakres mieszany: przydatne podstawy, starsze ścieżki udostępniania i raportów.',
 'Instrukcja nadal publikowana przez ZPE; dostępność modułu na Twoim koncie niepotwierdzona.',
 'Starszy model udostępniania. Nie odpowiada ekranowi kursów z konta prowadzącego.',
 'Podstawowe możliwości potwierdzone publiczną pomocą ZPE; szczegółowe ekrany PDF-u nieprzetestowane.',
 'Starsza procedura ścieżek. Dla kursów korzystaj z instrukcji etapów kursu.',
 'Starsza nawigacja użytkowników. Pomoc kursów prowadzi przez Platforma → Uczniowie.',
 'Starszy formularz grup. Nie jest instrukcją zapisów do obecnego kursu.',
 'Starsze ekrany klas i zaproszeń. Obecny poradnik kursów opisuje inną nawigację.',
 'Opis starszego modułu Wiadomości; dostępność na obecnym koncie niepotwierdzona.',
 'Katalog funkcji przydatny; obsługa i nazwy części komponentów różnią się od przewodnika WWW.',
 'Starszy panel zaawansowany; nie potwierdzono jego dostępności na obecnym koncie.'
];
const CHAPTERS=[['wprowadzenie','ZPE i sprzęt w szkole'],['plan','Plan szkolenia'],['modele','Uczniowie pracują'],['konto','Konto i dostęp'],['szukanie','Wyszukiwanie'],['wybor','Wybór i zapis'],['uzytkownicy','Użytkownicy i grupy'],['udostepnianie','Od lekcji do oceny'],['kreator','Kreator: pełny przewodnik'],['baza','Narzędzia ZPE'],['praca','Mój temat'],['biblioteka','Materiały i poradniki']];
document.getElementById('chapter-nav').innerHTML=CHAPTERS.map(([id,title],i)=>`<a href="#${id}"><span>${String(i+1).padStart(2,'0')}</span>${title}</a>`).join('');

const hero=`<section class="hero" id="start"><p class="eyebrow">ZPE bez pośpiechu / szkoła ponadpodstawowa</p><h1>ZPE na lekcji.<br><em>Od zasobu do własnych zadań.</em></h1><p class="lede">Podczas szkolenia pracujemy bezpośrednio w ZPE. Tutaj znajdziesz wprowadzenie, plan spotkania i instrukcje do samodzielnego powrotu — od pracy z gotowymi lekcjami po możliwości Kreatora e-materiałów.</p><div class="hero-links"><a class="button" href="#od-lekcji-do-oceny">Od lekcji do oceny <span aria-hidden="true">↓</span></a><a class="button secondary" href="#biblioteka">Poradniki i pliki →</a></div><div class="hero-image"><img src="assets/przewodnik/katalog.jpg" alt="Katalog ZPE: zapytanie, wybór etapu i przedmiotu, filtry oraz lista materiałów" width="1722" height="782" fetchpriority="high"></div><p class="hero-source">Ekran z przekazanego poradnika ZPE, s. 7. ${source(0,7,'Zobacz dokument')}</p></section>`;

const introduction=chapter('wprowadzenie','01','Czym jest ZPE i po co nam szkolny sprzęt?','Gotowe materiały, własne zadania i praca z klasą w jednym miejscu. Zaczynamy od możliwości, które można wykorzystać na zwykłej lekcji.',`
<p><strong>Zintegrowana Platforma Edukacyjna (ZPE)</strong>, dostępna pod adresem ${external('https://zpe.gov.pl/','zpe.gov.pl')}, to publiczna, bezpłatna platforma Ministerstwa Edukacji Narodowej. Udostępnia e-materiały dla różnych etapów kształcenia, w tym dla szkół ponadpodstawowych i kształcenia zawodowego. Zasoby platformy powstawały i były rozwijane m.in. w projektach edukacyjnych współfinansowanych z funduszy europejskich. ZPE jest platformą, na której można z tych zasobów korzystać oraz przygotowywać własne materiały.</p>
<div class="grid-3"><article class="tile"><h3>Wybierz gotowy fragment</h3><p>Tekst, film, ilustracja, symulacja lub ćwiczenie może posłużyć do jednego konkretnego zadania. Nie trzeba realizować całego e-materiału.</p></article><article class="tile"><h3>Ułóż własną lekcję</h3><p>Zapisuj zasoby w Ulubionych, zbieraj fragmenty w Teczce i opracowuj je w Kreatorze. Dodawaj własne polecenia, multimedia oraz ćwiczenia.</p></article><article class="tile"><h3>Pracuj z uczniami</h3><p>Dodawaj materiały do kursów, zapisuj uczniów i korzystaj z dostępnych odpowiedzi oraz raportów. ZPE może wspierać pracę własną, pracę w parach i wspólne omawianie rozwiązań.</p></article></div>
${cite(0,2,'Możliwości platformy')}${cite(0,14,'Własne materiały')}
<h3 class="subsection">Mamy sprzęt — korzystajmy z niego na lekcjach</h3><p>Szkoła otrzymała dużo komputerów i iPadów. Część sprzętu jest już rozłożona w salach. Kolejne urządzenia będą udostępniane wraz z zakończeniem zakupów i przygotowaniem szaf do bezpiecznego przechowywania w salach funkcyjnych. Termin udostępnienia pozostałego sprzętu zależy od zakończenia tych przygotowań.</p>
<p>Nie trzeba zaczynać od rozbudowanej lekcji cyfrowej. Na początek wystarczy jeden zasób i jedno zadanie. Zwykłe korzystanie ze sprzętu zgodnie z zasadami jest jego przeznaczeniem — warto dać sobie i uczniom przestrzeń, żeby się tego nauczyć.</p>
<h3 class="subsection">Telefon to inne doświadczenie niż komputer</h3><p>Z obserwacji prowadzącego na lekcjach informatyki wynika, że część uczniów sprawnie korzysta z telefonu, ale przy komputerze czuje niepewność. Otwarcie przeglądarki, wpisanie adresu, przełączanie kart czy odnalezienie pliku może wymagać pokazania. Na początku warto spokojnie wyjaśnić te czynności i upewnić się, że uczniowie wiedzą, co zrobić.</p>
<div class="grid-2"><article class="tile"><h3>Proste zasady od początku</h3><ul><li>Komputer lub iPad pozostaje na biurku.</li><li>Ekran ustawiamy tak, aby nauczyciel widział wykonywaną pracę.</li><li>Otwieramy wskazany materiał i wykonujemy konkretne polecenie.</li><li>Gdy coś nie działa, zgłaszamy problem i prosimy o pomoc.</li></ul><p>To prosty punkt wyjścia do spokojnej organizacji lekcji.</p></article><article class="tile"><h3>Spójrz na pracę z tyłu sali</h3><p>Kiedy uczniowie pracują samodzielnie, można na chwilę stanąć z tyłu sali. Widoczne ekrany ułatwiają zauważenie, kto pracuje w ZPE, kto otworzył inną stronę, a kto utknął i potrzebuje wsparcia.</p><p>Potem warto podejść do konkretnych osób i zapytać o odpowiedź lub sposób rozwiązania zadania.</p></article></div>
<p class="source-line">Informacje o wyposażeniu szkoły i obserwacje dotyczące pracy uczniów pochodzą od prowadzącego. Instrukcje funkcji ZPE w dalszych rozdziałach oparto na załączonych poradnikach.</p>`);

const trainingPlan=chapter('plan','02','Plan szkolenia: pracujemy bezpośrednio w ZPE','Strona jest przewodnikiem do powrotu po spotkaniu. Poszczególne czynności wykonujemy na platformie ZPE.',`
${steps([
 ['Logowanie i rozpoznanie konta','Wejście na zpe.gov.pl, logowanie oraz różnice między kontem szkolnym z SIO a kontem założonym samodzielnie. <a href="#konto">Konto i dostęp →</a>'],
 ['Wyszukiwanie materiałów','Słowa kluczowe, etap edukacyjny, przedmiot, podstawa programowa i materiały zawodowe. <a href="#szukanie">Wyszukiwanie →</a>'],
 ['Ulubione','Zapisanie zasobu na koncie i ponowne otwarcie go z listy. <a href="#wybor">Wybór i zapis →</a>'],
 ['Teczka','Zebranie fragmentów z różnych materiałów, przejście do ich edycji i przygotowanie własnego zestawu. <a href="#teczka">Instrukcja Teczki →</a>'],
 ['Użytkownicy, grupy i dostęp','Tworzenie grup, dodawanie uczestników, zaproszenia oraz dostępne na uprawnionym koncie opcje odzyskania dostępu ucznia. <a href="#uzytkownicy">Użytkownicy i grupy →</a>'],
 ['Własne materiały w Kreatorze','Nowy projekt, treść, multimedia i ćwiczenia. Przegląd możliwości pozostaje na tej stronie dla osób, które chcą pójść dalej. <a href="#kreator">Pełny przewodnik po Kreatorze →</a>'],
 ['Udostępnianie i odpowiedzi uczniów','Dodanie lekcji do kursu, publikacja, zapisanie uczniów i odszukanie wyników w zakładce „Analiza”. <a href="#udostepnianie">Udostępnianie i wyniki →</a>']
])}`);

const lessonExamples=()=>'<div class="grid-2 subsection">'+DATA.case_examples.map(example=>{
 const resource=example.resource_id?DATA.resources.find(r=>r.id===example.resource_id):null;
 return '<article class="example case-example"><span class="tag">'+escapeHTML(example.subject)+'</span><h3>'+escapeHTML(example.title)+'</h3><p>'+escapeHTML(example.context)+'</p><dl><dt>Materiał</dt><dd>'+escapeHTML(example.material)+'</dd><dt>Polecenie dla ucznia</dt><dd>'+escapeHTML(example.task)+'</dd><dt>Oczekiwana odpowiedź</dt><dd>'+escapeHTML(example.answer)+'</dd></dl><p class="result"><strong>Rola nauczyciela:</strong> '+escapeHTML(example.teacher)+'</p><p class="source-line"><strong>Hasła do szukania:</strong> '+escapeHTML(example.keywords.join('; '))+'</p>'+external(resource?resource.url:'https://zpe.gov.pl/',resource?'Otwórz materiał ZPE':'Otwórz ZPE i wyszukaj temat')+'</article>';
}).join('')+'</div>';

const handover=(tag,title,students,zpe,teacher,href,label)=>`<article class="tile"><span class="tag">${tag}</span><h3>${title}</h3><p>${students}</p><p><strong>Z ZPE:</strong> ${zpe}</p><p><strong>Nauczyciel:</strong> ${teacher}</p><p class="source-line">${external('https://metodyka.covepolska.pl/'+href,label)}</p></article>`;
const shopResource=DATA.resources.find(r=>r.id==='handlowiec');

const models=chapter('modele','01','Lekcja, w której pracują uczniowie','Nauczyciel robi tylko część pracy: krótko wprowadza i stawia zadanie. Resztę oddaje uczniom, a materiał ZPE daje im to, z czym pracują.',`
<div class="flow" aria-label="Rytm lekcji"><span>Wprowadzam krótko</span><b>→</b><span>Oddaję pracę</span><b>→</b><span>Sprawdzamy</span><b>→</b><span>Decyduję, co dalej</span></div>
<p>Wprowadzenie to jeden przykład i jasne polecenie. Potem uczniowie działają sami, w parach albo w grupach, a na końcu mają odpowiedź, uzupełnioną kartę pracy lub własną ocenę z uzasadnieniem. Nauczyciel w tym czasie chodzi między ławkami, słucha i pomaga tam, gdzie ktoś utknął. Odpowiedzi klasy mówią mu, co zrobić dalej.</p>
<h3 class="subsection">Jak oddać część pracy uczniom?</h3>
<div class="grid-3">${[
 handover('Para','Jeden rozwiązuje, drugi sprawdza','Uczeń rozwiązuje zadanie i mówi na głos, co robi. Partner porównuje kroki z materiałem i pyta „skąd to wiesz?”. Potem zamieniają się rolami.','ćwiczenie, przykład rozwiązany krok po kroku, fragment do porównania.','słucha par i wyłapuje błąd, który powtarza się w kilku z nich.','metoda-wspolpraca.html','Współpraca: tutoring w parach'),
 handover('Grupa','Każdy przynosi inny fragment','Członkowie grupy czytają różne części materiału i wspólnie uzupełniają kartę pracy. Informacje z każdego fragmentu są potrzebne, aby odpowiedzieć na wszystkie pytania.','kilka sekcji jednego e-materiału albo fragmenty kilku materiałów zebrane w Teczce.','przydziela fragmenty i na końcu pyta każdego osobno.','metoda-wspolpraca.html','Współpraca: grupy z rolami'),
 handover('Praca własna','Tekst do przeszukania','Uczeń szuka w materiale odpowiedzi na kilka pytań i zaznacza, skąd je wziął. Pracuje we własnym tempie: wraca do akapitu, zatrzymuje film, powiększa ilustrację.','tekst, grafika, nagranie, słownik pojęć, ćwiczenia z natychmiastowym sprawdzeniem.','siada przy osobach, które utknęły, zamiast tłumaczyć wszystkim to samo.','method-1.html','360 e-learning'),
 handover('Lekcja odwrócona','Najpierw materiał, potem zadania','Uczeń zapoznaje się z krótkim fragmentem przed lekcją i zapisuje jedno pytanie. Lekcja zaczyna się od tych pytań i służy pracy nad zadaniami.','krótki film lub fragment udostępniony klasie, pytanie otwarte do odpowiedzi przed lekcją.','ma krótkie podsumowanie dla osób, które się nie przygotowały, żeby lekcja nie zależała od pracy domowej.','method-3.html','Flipped classroom'),
 handover('Problem i przypadek','Decyzja na podstawie danych','Uczniowie dostają realistyczną sytuację z zawodu lub przedmiotu, analizują dane i podejmują decyzję z uzasadnieniem.','źródło danych do przypadku: opis, schemat, infografika, przepis albo instrukcja.','podaje dane, pilnuje uzasadnień i prowadzi rozmowę o różnych decyzjach.','metoda-problem-projekt-przypadek.html','Problem, przypadek, projekt')
].join('')}</div>
<div class="example"><span class="tag">Przykład lekcji / handlowiec, sprzedawca</span><h3>Gdzie postawić towar na regale?</h3><p>${escapeHTML(shopResource.title)}: słownik pojęć e-materiału jako źródło do przypadku. Nauczyciel udostępnia materiał klasie w ZPE.</p>${steps([
 ['Wprowadzam krótko','Nauczyciel pokazuje zdjęcie regału w sklepie i pyta: „Dlaczego ten towar stoi na wysokości oczu?”. Zbiera kilka odpowiedzi i zapowiada zadanie: klasa zdecyduje, jak ułożyć regał.'],
 ['Praca własna z tekstem','Uczniowie otwierają udostępniony e-materiał. W słowniku pojęć odszukują strefy wysokości regału i zapisują ich granice.'],
 ['Przypadek w grupach','Każda grupa dostaje cztery towary: nowy baton, kawę z najwyższą marżą, zgrzewkę wody i sól. Decyduje, gdzie je postawić, i przy każdym towarze podaje strefę oraz powód.'],
 ['Sprawdzamy','Grupy porównują układy. Nauczyciel pyta: „Która definicja rozstrzyga tę różnicę?”. Na koniec każdy uczeń sam zapisuje, gdzie postawi nowy produkt i dlaczego.'],
 ['Decyduję, co dalej','Jeśli wielu uczniów myli strefy, klasa wraca do definicji na nowym przykładzie. Jeśli nie, kolejnym zadaniem jest ekspozycja całej kategorii towarów.']
])}<div class="actions">${external(shopResource.url,'Otwórz e-materiał ZPE')}${external('https://metodyka.covepolska.pl/metoda-problem-projekt-przypadek.html','Metoda przypadku w katalogu COVE')}</div></div>
<h3 class="subsection">Zadania do oddania uczniom: przedmioty i zawody</h3><p>Każde zadanie opiera się na konkretnym materiale ZPE. Można je dać parze, grupie albo do pracy własnej.</p>
${lessonExamples()}
<p class="source-line">Opis każdej metody z przebiegiem lekcji i materiałami: ${external('https://metodyka.covepolska.pl/','katalog 12 metod COVE')}</p>`);

const account=chapter('konto','02','Konto: co naprawdę ma znaczenie?','Brak widocznej klasy albo funkcji nie musi oznaczać błędu. Najpierw warto ustalić, na jakim koncie pracujemy.',`
<h3>Jak się zalogować?</h3>${steps([['Otwórz platformę','Wejdź na zpe.gov.pl i wybierz „Zaloguj się”.'],['Wpisz dane właściwego konta','Użyj loginu i hasła otrzymanego dla konta szkolnego lub danych konta założonego samodzielnie. Wielkość liter w haśle ma znaczenie.'],['Sprawdź kontekst pracy','Po zalogowaniu sprawdź szkołę, rolę i dostępne klasy. Klasy importowane ze szkoły są związane z kontem z SIO.']])}<p>Dane konta szkolnego uzyskasz w szkole. Dostęp do klas zależy także od wybranej szkoły lub przestrzeni — na ekranie prowadzącego jest osobny wybór przestrzeni. Poradnik pokazuje również pobieranie danych ze Strefy Pracownika SIO; przedstawiony w nim rok szkolny jest przykładem z czasu opracowania instrukcji. Konto samodzielne zakłada się przez „Zaloguj się” → „Zarejestruj się”, a następnie aktywuje linkiem z wiadomości e-mail i ustawia hasło.</p>${cite(0,4,'Dane konta szkolnego — s. 4–5')}${cite(0,5,'Logowanie i rejestracja — s. 5–6')}
<div class="table-wrap"><table><thead><tr><th>Sposób dostępu</th><th>Do czego służy</th><th>Co sprawdzić</th></tr></thead><tbody><tr><td><strong>Bez logowania</strong></td><td>Przeglądanie publicznych materiałów i wybór zasobów.</td><td>Czy wybrany zasób faktycznie jest publiczny. Nie oczekuj listy Ulubionych zapisanej na koncie.</td></tr><tr><td><strong>Konto założone samodzielnie</strong></td><td>Własne materiały i dostępne funkcje pracy na platformie.</td><td>Nie jest automatycznie tym samym kontem co konto oparte na SIO.</td></tr><tr><td><strong>Konto oparte na danych SIO</strong></td><td>Praca w kontekście szkoły, w tym dostęp do zaimportowanych klas, jeśli przypisanie jest prawidłowe.</td><td>Właściwą szkołę, rolę i dostępność klas. Pomocy w dostępie szukaj w szkole i oficjalnym wsparciu.</td></tr></tbody></table></div>
<div class="tile"><span class="tag">Gdy coś nie działa</span><h3>Nie ma mojej klasy</h3><p>Poradnik wskazuje, że klasy importowane ze szkoły są związane z kontem opartym na SIO. Konto utworzone samodzielnie może funkcjonować niezależnie.</p><p><strong>Najpierw:</strong> sprawdź użyte konto i przypisanie do szkoły. Tworzenie kolejnego konta bez rozpoznania sytuacji może tylko utrudnić odnalezienie materiałów.</p><p>Dane logowania uczestnicy wpisują wyłącznie w ZPE. Strona szkolenia nie zbiera haseł.</p></div>
${cite(0,5,'Logowanie i różnice między kontami')}`);

const search=chapter('szukanie','03','Wyszukiwanie dla szkoły ponadpodstawowej','Zaczynamy od hasła lub katalogu i wybieramy właściwy etap oraz przedmiot. Katalog pozwala też zawęzić wyniki do punktu podstawy programowej.',`
<div class="flow" aria-label="Ścieżka wyszukiwania"><span>Temat lub pojęcie</span><b>→</b><span>Etap i przedmiot</span><b>→</b><span>Lista wyników</span><b>→</b><span>Dokładny fragment</span></div>
<div class="split"><div><span class="tag">Droga A / słowo kluczowe</span><h3>Zacznij od pojęcia, nie od całego tematu lekcji</h3>${steps([['Wpisz hasło','Na przykład „obliczenia procentowe”, „ciasto drożdżowe” albo „fotosynteza”.'],['Uruchom wyszukiwanie','W poradniku służy do tego ikona lupki. W tym samym obszarze można wybrać etap edukacyjny.'],['Doprecyzuj zakres','Na ekranie wyników wybierz przedmiot. Przy szerokim haśle ograniczenie zakresu jest zwykle bardziej pomocne niż dopisywanie całego zdania.']])}</div>${figure('wyszukiwarka.jpg','Pole zapytania i wybór etapu',0,8,'Czerwona ramka pochodzi z poradnika i wskazuje pole zapytania.')}</div>
<div class="example"><span class="tag">Przykład wyszukiwania / temat zawodowy</span><h3>Od „ciasta” do receptury cukierniczej</h3><dl><dt>Pierwsza próba</dt><dd>„Ciasto” — hasło szerokie, może obejmować różne rodzaje materiałów.</dd><dt>Zawężenie</dt><dd>„Ciasto drożdżowe” — nazwa treści, której rzeczywiście potrzebujemy.</dd><dt>Kolejna próba</dt><dd>Symbol kwalifikacji „SPC.01” albo nazwa czynności, np. „dobór surowców” — inny punkt wejścia, gdy tytuł zasobu używa innego słownictwa.</dd><dt>Weryfikacja</dt><dd>Otwieramy wynik i sprawdzamy, czy prowadzi do treści dla ucznia, czy do przewodnika nauczyciela.</dd></dl><p class="result">Porównaj wyniki dla dwóch lub trzech zapytań i wybierz zasób najlepiej dopasowany do tematu.</p></div>
<div class="split reverse">${figure('katalog.jpg','Katalog, filtry i wyniki',0,7,'Przykład z poradnika: chemia. Na szkoleniu wybieramy etap ponadpodstawowy i własny przedmiot.')}<div><span class="tag">Droga B / katalog</span><h3>Gdy znasz przedmiot, ale nie tytuł zasobu</h3>${steps([['Wybierz etap','W katalogu zacznij od poziomu kształcenia. Nie oceniaj przydatności materiału wyłącznie po jego okładce.'],['Wybierz przedmiot','Przeglądaj tytuły i opisy. Zwróć uwagę na rozróżnienie materiałów edukacyjnych oraz scenariuszy i poradników.'],['Użyj dostępnych filtrów','Poradnik pokazuje m.in. typ i język materiału. Dodawaj ograniczenia kolejno, aby wiedzieć, które z nich zmieniło wynik.']])}</div></div>
${detail('Podstawa programowa i materiały zawodowe',`<div class="split"><div><span class="tag">Filtr podstawy programowej</span><h3>Wybierz punkt podstawy, a lista się zawęzi</h3><p>Po wybraniu w katalogu etapu i przedmiotu w górnej części strony pojawia się przycisk podstawy programowej. Wybór punktu ogranicza listę do materiałów z nim powiązanych. Filtr usuwa się ikoną X przy nazwie przedmiotu albo wyborem innego punktu.</p><p><strong>Kształcenie zawodowe:</strong> ZPE ma osobny dział z e-materiałami do kwalifikacji, a podstawa programowa jest tam ułożona według branż, np. HAN.01, HGT.02, SPC.01. Hasłem może być też symbol kwalifikacji.</p>${cite(0,8,'Podstawa programowa — s. 8–9')}</div>${figure('podstawa.jpg','Przycisk podstawy programowej',0,9,'Przykład z poradnika dla szkoły podstawowej; w szkole ponadpodstawowej wybieramy własny etap i przedmiot.')}</div>`)}
<div class="grid-2"><article class="tile"><h3>Za dużo wyników</h3><ul><li>Dodaj przedmiot lub etap.</li><li>Zastąp ogólne hasło nazwą pojęcia albo procesu.</li><li>Rozróżnij materiał ucznia i poradnik nauczyciela.</li><li>Oceń opis, zanim otworzysz kolejny wynik.</li></ul></article><article class="tile"><h3>Brak wyników</h3><ul><li>Usuń ostatnio dodany filtr.</li><li>Skróć zapytanie; sprawdź synonim.</li><li>W zawodzie spróbuj nazwy czynności lub symbolu kwalifikacji.</li><li>Wróć do katalogu i przejrzyj właściwy dział.</li></ul></article></div>
<div class="tip"><strong>Ważne rozróżnienie:</strong> „nie ma wyniku dla tego zapytania” nie oznacza „nie ma materiału na platformie”. Zapytanie i filtry to narzędzia, które można zmieniać.</div>${cite(0,7,'Katalog, słowa kluczowe i podstawa programowa — s. 7–9')}`);

const selection=chapter('wybor','04','Od wyniku do przydatnego fragmentu','Nie chodzi o obejrzenie całego zasobu. Chodzi o znalezienie tego, co rzeczywiście pomoże w pracy z konkretną klasą.',`
<div class="table-wrap"><table><thead><tr><th>Sprawdzamy</th><th>Na co patrzeć</th><th>Przykład decyzji</th></tr></thead><tbody><tr><td><strong>Odbiorca</strong></td><td>Język, wymagane wiadomości, etap i przeznaczenie materiału.</td><td>Prosty film może służyć powtórzeniu, ale oprawa dla młodszych uczniów może utrudniać odbiór w technikum.</td></tr><tr><td><strong>Treść</strong></td><td>Dokładny temat, przykład, ćwiczenie, poprawność i źródła.</td><td>Z całego zasobu wybieramy jedną infografikę odpowiadającą omawianemu zagadnieniu.</td></tr><tr><td><strong>Aktualność</strong></td><td>Daty, przepisy, normy i procedury zawodowe.</td><td>E-materiały zawodowe podają stan prawny z dnia opracowania. Przepisy, normy i instrukcje porównujemy z obecnymi.</td></tr><tr><td><strong>Dostępność</strong></td><td>Działanie multimediów, czytelność, wersja tekstowa i urządzenie.</td><td>Jeżeli film nie działa na stanowisku, wybieramy dostępną treść alternatywną lub inny zasób.</td></tr></tbody></table></div>
<div class="split"><div><h3>Jak zachować materiał i nie szukać od nowa?</h3>${steps([['Zapis na koncie','Na zalogowanym koncie użyj serca „Dodaj do ulubionych”. Powtórne kliknięcie może cofnąć zapis.'],['Powrót do listy','Obecny poradnik WWW prowadzi przez Katalog → Ulubione. Ścieżka przez „Moje materiały” pochodzi ze starszego PDF-u.'],['Zapis adresu','Pełny link do publicznego zasobu możesz również zachować w swoich notatkach lub zakładkach przeglądarki. To osobny mechanizm od Ulubionych ZPE.'],['Próba ponownego otwarcia','Otwórz zapisany materiał i sprawdź, czy trafiasz do właściwego zasobu. Adres całego materiału nie zawsze wskazuje dokładną podsekcję.']])}<h3 class="subsection" id="teczka">Teczka: kilka fragmentów w jednym materiale</h3><p>Ulubione pomagają wracać do całych zasobów. Teczka służy zbieraniu wybranych elementów, z których przygotujesz własny materiał.</p>${steps([['Włącz Teczkę i wybierz fragment','Po zalogowaniu otwórz panel Teczki w prawym górnym rogu i włącz przełącznik. Przy wybranym elemencie materiału użyj plusa.'],['Zbierz zestaw','Otwieraj kolejne zasoby i dodawaj potrzebne fragmenty. Mogą pochodzić z różnych materiałów i przedmiotów.'],['Opracuj zawartość','W Teczce wybierz „Utwórz materiał z elementów”. Obecny poradnik wskazuje zapis w Katalog → Moje. Otwórz utworzony materiał w Kreatorze, aby go uporządkować i dodać polecenia.'],['Udostępnij','Dodaj przygotowany materiał do kursu, opublikuj kurs i zapisz uczniów. Sprawdź dostęp z perspektywy odbiorcy.']])}<p><strong>Przykład:</strong> połącz ilustrację stanowiska pracy, fragment instrukcji i własne pytanie o kolejność czynności. Uczeń korzysta z jednego przygotowanego zestawu.</p>${currentHelp('https://zpe.gov.pl/a/ulubione/DE1FP3VBC','Ulubione i Teczka')}</div><div><figure class="image-card"><button type="button" data-zoom="assets/ulubione-serce.png" data-title="Serce na stronie materiału" data-caption="Publiczna instrukcja Ulubione ZPE, ilustracja dołączona wcześniej do pakietu." aria-label="Powiększ: serce na stronie materiału"><img src="assets/ulubione-serce.png" alt="Ikona serca na stronie materiału ZPE" loading="eager"></button><span class="zoom-label">Powiększ ekran →</span><figcaption>Serce na stronie materiału. Źródło: publiczna instrukcja Ulubione wskazana poniżej.</figcaption></figure><p class="source-line">${external(DATA.sources[1][1],'Publiczna instrukcja Ulubione — źródło ilustracji')}</p></div></div>
<div class="tip"><strong>Szukaj materiałów z pytaniami otwartymi.</strong> Poradnik ZPE zaleca je w pierwszej kolejności: ćwiczenia zamknięte łatwo sprawdzić, ale to pytania otwarte skłaniają uczniów do wniosków i dają materiał do rozmowy. Odpowiedzi uczniów przypisanych do kursu sprawdzaj w kursie, zgodnie z instrukcją w następnym rozdziale. ${source(0,19,'Praktyczne wskazówki')}</div>
<div class="notice"><strong>Wersje ekranu mogą się różnić.</strong> Poradniki pochodzą z różnych etapów rozwoju platformy. Nazwy i rozmieszczenie przycisków porównaj z aktualnym widokiem ZPE.</div>`);

const sharing=chapter('udostepnianie','08','Udostępnianie i wyniki: co wybrać?','Gotowe materiały ZPE: zbierasz lekcje, udostępniasz je klasie i sprawdzasz odpowiedzi. Bez tworzenia własnych zasobów.',`
<div class="notice"><strong>Instrukcja poprawiona po sprawdzeniu źródeł.</strong> Ekran „Udostępnianie treści” z konta prowadzącego pokazuje wybór nowego lub istniejącego kursu. Potwierdza to poradnik WWW „Prowadzenie kursów”. Starszy PDF opisuje inny model; jego kodów dostępu i raportów w „Moich materiałach” nie należy przenosić do tej procedury.</div>
<h3 id="od-lekcji-do-oceny" class="subsection">Od gotowej lekcji do sprawdzenia pracy uczniów</h3>
<p>Ten sposób pracy nie wymaga tworzenia własnych materiałów ani używania Kreatora. Korzystasz z gotowych lekcji dostępnych w ZPE, stopniowo udostępniasz je klasie i sprawdzasz odpowiedzi na swoim komputerze. Zwykłą zewnętrzną stronę możesz wskazać uczniom linkiem, ale nie oznacza to zbierania jej wyników w ZPE.</p>
<div class="flow workflow-map" aria-label="Kolejność pracy"><span>Ulubione</span><b aria-hidden="true">→</b><span>Klasa lub grupa</span><b aria-hidden="true">→</b><span>Kurs</span><b aria-hidden="true">→</b><span>Publikacja i zapis uczniów</span><b aria-hidden="true">→</b><span>Praca uczniów</span><b aria-hidden="true">→</b><span>Analiza i informacja zwrotna</span></div>
<ol class="workflow-steps">
<li><div class="workflow-body"><span class="tag">Nauczyciel / bank materiałów</span><h4>Zbieram gotowe lekcje w Ulubionych</h4><p>Wyszukuję ciekawy materiał ZPE, otwieram go i klikam serce. Wracam do niego przez <strong>Katalog → Ulubione</strong>. Mogę tam zebrać materiały na cały semestr.</p><p class="result"><strong>Co widzi uczeń?</strong> Zapisanie zasobu w moich Ulubionych niczego mu nie przypisuje.</p><a href="#wybor">Zobacz ikonę serca i instrukcję zapisu →</a></div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / odbiorcy</span><h4>Wybieram klasę albo przygotowuję grupę</h4><p>Sprawdzam, czy właściwa klasa jest dostępna na moim koncie szkolnym. Jeśli tak, korzystam z niej — nie tworzę drugiej grupy z tymi samymi osobami. Gdy potrzebuję innego zestawu uczniów, otwieram <strong>Platforma → Uczniowie</strong>, zaznaczam osoby i używam dostępnych opcji grup.</p><p class="result"><strong>Przykład:</strong> wybieram klasę 1PF. Dla koła zainteresowań przygotowuję osobną grupę.</p><a href="#uzytkownicy">Użytkownicy i grupy krok po kroku →</a></div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / organizacja lekcji</span><h4>Tworzę kurs dla tej klasy</h4><p>Otwieram pierwszą wybraną lekcję i klikam <strong>Udostępnij → Platforma edukacyjna</strong>, jeśli wyświetla się ten wybór. Wybieram właściwą szkołę lub przestrzeń, a następnie nowy kurs, np. <strong>„Informatyka — 1PF — 2026/2027”</strong>. Dodaję lekcję do kursu.</p><p>Dla kilku klas pracujących w różnym tempie wygodne są osobne kursy, np. 1PF i 1TF. To wybór organizacyjny: jeden kurs można też udostępnić kilku grupom, ale wtedy publikowane zmiany są wspólne dla jego uczestników.</p><p class="result"><strong>Co mam gotowe?</strong> Kurs z pierwszą lekcją. Materiały na później nadal czekają w Ulubionych.</p>${currentHelp('https://zpe.gov.pl/a/dodawanie-materialow-do-kursu/D2F5EFRLV','Dodanie gotowej lekcji do kursu')}</div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / pierwsze udostępnienie</span><h4>Publikuję kurs i zapisuję uczniów</h4><p>Klikam <strong>„Opublikuj”</strong>. Następnie w kursie wybieram <strong>Uczniowie → Zapisz uczniów</strong>, wskazuję osoby lub właściwą grupę, przechodzę dalej i zatwierdzam zapis. Mogę ustawić okres dostępu.</p><div class="tip"><strong>To nie jest publikacja dla całego internetu.</strong><p>Utworzenie kursu i nadanie mu nazwy nie udostępnia go wszystkim użytkownikom ZPE. „Opublikuj” przygotowuje wersję dla zapisanych uczestników. Kurs w przestrzeni szkolnej może też podlegać uprawnieniom administracyjnym tej przestrzeni.</p></div><p class="result"><strong>Co widzi uczeń?</strong> Po zapisaniu i uzyskaniu dostępu może otworzyć opublikowane lekcje swojego kursu.</p>${currentHelp('https://zpe.gov.pl/a/zapisywanie-uczniow/D2UOTPKJV','Publikacja i zapis klasy')}</div></li>
<li><div class="workflow-body"><span class="tag">Uczeń / na lekcji lub w domu</span><h4>Uczeń otwiera kurs i wykonuje wskazane zadania</h4><p>Uczeń loguje się na swoje konto, otwiera przypisany kurs i wybraną lekcję. Podaję mu dokładny zakres pracy, np. „Przeczytaj wskazany fragment i wykonaj zadania 1–4 w części Sprawdź się”.</p><p>Uczeń wypełnia zadania i używa dostępnych przycisków zatwierdzenia lub sprawdzenia. Przed pierwszą pracą na ocenę sprawdzam na koncie testowym, czy te konkretne ćwiczenia zapisują odpowiedzi w kursie.</p><p class="result"><strong>Ważne:</strong> otwarcie publicznego adresu lekcji poza przypisanym kursem nie zastępuje pracy w moim kursie.</p></div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / kolejne lekcje</span><h4>Dodaję następną lekcję wtedy, gdy jest potrzebna</h4><p>Wracam do Ulubionych, wybieram kolejny zasób i dodaję go do istniejącego kursu 1PF. Mogę też w kursie użyć <strong>„Dodaj element”</strong> i wybrać materiał.</p><div class="table-wrap"><table><thead><tr><th>Co klikam?</th><th>Co się dzieje?</th></tr></thead><tbody><tr><td><strong>Zapisz</strong></td><td>Zachowuję zmiany robocze. Uczniowie nadal korzystają z poprzedniej opublikowanej wersji.</td></tr><tr><td><strong>Opublikuj</strong></td><td>Udostępniam najnowszą wersję całego kursu, z uwzględnieniem ustawionych ograniczeń etapów.</td></tr></tbody></table></div><p><strong>Nie jest to przełącznik jednej lekcji.</strong> Jeśli w wersji roboczej dodam kilka materiałów bez ograniczeń, ponowna publikacja udostępni je wszystkie. Dlatego na początek materiały na później trzymam w Ulubionych, a do kursu dodaję to, z czym klasa ma już pracować. Do planowania dostępu z góry służą ustawienia etapów.</p>${currentHelp('https://zpe.gov.pl/a/etapy-kursu/D8BVAQD3N','Dodawanie lekcji i ograniczenia etapów')}</div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / sprawdzanie przy swoim komputerze</span><h4>Otwieram wyniki klasy i odpowiedzi konkretnego ucznia</h4><p>Wchodzę do edycji kursu, otwieram <strong>„Analiza” → „Pokaż szczegółowy raport”</strong>. Rozwijam grupę i w razie potrzeby filtruję wyniki. Następnie otwieram konkretny materiał i wybieram ucznia w panelu po prawej, aby zobaczyć jego odpowiedzi w ćwiczeniach.</p><p>Sprawdzam, co uczeń zaznaczył lub wpisał, które zadania wykonał i gdzie pojawił się błąd. Nie muszę podchodzić do każdego stanowiska, żeby obejrzeć odpowiedzi zapisane w obsługiwanych ćwiczeniach.</p>${currentHelp('https://zpe.gov.pl/a/monitorowanie-postepow/D8OONO24C','Raport i odpowiedzi ucznia')}
${detail('Zobacz przykłady ekranów z PDF-u: uczeń i rozwiązania',`<p><strong>Ilustracje ze starszego interfejsu.</strong> Pokazują rodzaj informacji: wybór ucznia, wynik i zaznaczone odpowiedzi. Nie przedstawiają obecnej ścieżki wejścia do raportu. W modelu kursów korzystaj z opisanej powyżej zakładki „Analiza”. Nazwiska są zamazane w źródłowym dokumencie.</p><div class="grid-2">${figure('odpowiedzi-przyklad.png','Przykład z PDF-u: panel wybranego ucznia',2,17,'Starszy ekran pokazujący panel ucznia i wynik. Nie jest to instrukcja nawigacji obecnego kursu.')}${figure('cwiczenie-odpowiedzi-przyklad.png','Przykład z PDF-u: odpowiedzi w zadaniach',2,18,'Zaznaczone odpowiedzi i informacja o poprawności w starszym interfejsie. Kliknij, aby powiększyć.')}</div><p>${external('https://zpe.gov.pl/a/monitorowanie-postepow/D8OONO24C','Zobacz także ekrany Analizy w obecnym poradniku WWW')}</p>`)}
<p class="result"><strong>Nie widzę odpowiedzi?</strong> Sprawdzam właściwy kurs, ucznia i materiał, dostęp uczestnika oraz zapis wyników danego ćwiczenia. Brak odpowiedzi nie wystarcza, by uznać, że uczeń nie pracował.</p></div></li>
<li><div class="workflow-body"><span class="tag">Nauczyciel / ocena i dalsza praca</span><h4>Daję informację zwrotną, wystawiam ocenę lub zlecam dokończenie</h4><p>Odpowiedzi zapisane w ZPE mogą być podstawą oceny wykonania zadania według kryteriów podanych klasie. Sprawdzam rozwiązania i uzasadnienia, a nie tylko końcowy procent. Przed pracą na ocenę ustalam zasady korzystania z podpowiedzi i klucza; poradnik kursów opisuje ustawienie pokazywania prawidłowych odpowiedzi.</p><p><strong>Ocena w dzienniku:</strong> po sprawdzeniu pracy wpisuję ją zgodnie z zasadami oceniania w szkole. Nie zakładam automatycznego przenoszenia ocen z ZPE do dziennika.</p><div class="example"><h4>Przykładowe polecenie do dokończenia w domu</h4><p>„W kursie Informatyka — 1PF otwórz dzisiejszą lekcję. Dokończ zadania 3 i 4 w części Sprawdź się do ustalonego terminu. Na kolejnej lekcji omówimy rozwiązania”.</p></div><p>Uczeń wraca do tej samej przypisanej lekcji, o ile nadal ma dostęp do kursu i etapu. Później ponownie sprawdzam zapisane odpowiedzi. Jeśli ćwiczenie nie pozwala na ponowną edycję lub nie zapisuje wyniku, ustalam z uczniem inny sposób oddania poprawy.</p><p class="result"><strong>Pamiętam:</strong> czas otwarcia materiału nie mierzy uwagi, a poprawna odpowiedź po użyciu klucza nie oznacza samodzielnego rozwiązania.</p></div></li>
</ol>

<h3 id="kurs-podrecznik" class="subsection">Kurs czy podręcznik modułowy — co wybrać?</h3>
<p><strong>Kurs</strong> to zestaw jednej lub wielu lekcji przygotowany dla wybranych uczniów. <strong>Podręcznik modułowy</strong> organizuje materiały jako moduły pogrupowane w wątki tematyczne. Oba rozwiązania pozwalają udostępniać treści uczniom i sprawdzać ich postępy. Różnica dotyczy przede wszystkim organizacji materiału i sposobu jego przygotowania.</p>
<div class="table-wrap"><table><thead><tr><th>Pytanie</th><th>Kurs</th><th>Podręcznik modułowy</th></tr></thead><tbody>
<tr><td>Do czego go użyję?</td><td>Do udostępnienia jednej lekcji albo zestawu materiałów, np. na dział, semestr lub zajęcia dodatkowe.</td><td>Do pracy z zestawem modułów uporządkowanych w wątki, który dostosowujesz do swojej klasy.</td></tr>
<tr><td>Jak porządkuję treść?</td><td>Dodajesz materiały; możesz podzielić je na etapy i ustawić warunki przechodzenia dalej.</td><td>Zmieniasz kolejność modułów w wątkach, ukrywasz wybrane moduły, usuwasz je lub dodajesz kolejne materiały.</td></tr>
<tr><td>Od czego zaczynam?</td><td>Otwierasz lekcję i dodajesz ją do nowego lub istniejącego kursu.</td><td>Możesz wybrać gotowy modułowy e-podręcznik i użyć „Przenieś do moich podręczników”, a potem modyfikować własną kopię.</td></tr>
<tr><td>Czy zobaczę wyniki?</td><td>Tak — dla obsługiwanych ćwiczeń i zapisanych uczestników, w zakładce „Analiza”.</td><td>Tak — w zakładce „Analiza” i po otwarciu konkretnego modułu. Poradnik opisuje również ocenianie odpowiedzi otwartych i komentarze.</td></tr>
</tbody></table></div>
<div class="tip"><strong>Co wybrać na początek?</strong><p>Jeśli chcesz zadać klasie „Orient i kulturę sarmacką” albo jedną lekcję informatyki, wybierz kurs z jednym materiałem. Jeśli chcesz dostosowywać cały zestaw tematyczny — dobierać, przestawiać i ukrywać moduły w wątkach — rozważ podręcznik modułowy. To wskazówka do wyboru; kurs również może obejmować wiele tematów.</p></div>
<p><strong>Podobne zasady dostępu:</strong> w obu przypadkach poradniki opisują publikację, a następnie zapis wybranych uczniów lub grup. Samo „Opublikuj” nie oznacza udostępnienia Twojej wersji wszystkim użytkownikom ZPE. Gotowy podręcznik dostępny publicznie w katalogu i Twoja dostosowana kopia to różne zasoby.</p>
<p>Gotowe modułowe e-podręczniki prezentowane w dziale ${external('https://zpe.gov.pl/modulowe','Modułowe e-podręczniki')} są przygotowane dla szkoły podstawowej. W szkole ponadpodstawowej sprawdź poziom i treść każdego wybranego modułu; sam fakt, że narzędzie umożliwia jego dodanie, nie przesądza o dopasowaniu do klasy.</p>
<p class="source-line">Porównanie na podstawie publicznej pomocy ZPE sprawdzonej 3.11.2026: ${external('https://zpe.gov.pl/a/dodawanie-materialow-do-kursu/D2F5EFRLV','Kursy')}, ${external('https://zpe.gov.pl/a/etapy-kursu/D8BVAQD3N','Etapy kursu')}, ${external('https://zpe.gov.pl/a/jak-dodac-modulowy-e-podrecznik-do-moich-podrecznikow/D6R39E8UF','Własna kopia podręcznika')}, ${external('https://zpe.gov.pl/a/jak-edytowac-modulowy-e-podrecznik/D4C6J71XM','Edycja modułów')}, ${external('https://zpe.gov.pl/a/jak-udostepnic-modulowy-e-podrecznik-uczniom/D3NBVQKSP','Udostępnianie podręcznika')}, ${external('https://zpe.gov.pl/a/jak-sprawdzac-postepy-pracy-uczniow-z-modulowym-e-podrecznikiem/DDA34JK3L','Postępy uczniów')}.</p>
<div class="grid-2"><article class="tile"><h3>Sam link do publicznej lekcji</h3><p>Pozwala otworzyć stronę, ale samo jego wysłanie nie zapisuje ucznia do Twojego kursu i nie tworzy dla Ciebie raportu pracy tej klasy.</p></article><article class="tile"><h3>Wynik konkretnego ćwiczenia</h3><p>Starszy PDF ostrzega o ćwiczeniach bez obsługi raportów. Nie potwierdzono, które zadania w konkretnej lekcji mają obecnie takie ograniczenie. Przed ocenianiem sprawdź wykonanie zadania i zapis odpowiedzi na koncie testowym ucznia.</p></article></div>
${detail('Starszy PDF: udostępnianie grupie lub kodem i raporty',`${olderProcedure}<p>Poradnik z 2022 r. pokazuje bezpośrednie udostępnienie istniejącej lub nowej grupie, kod dostępu, „Pokaż materiał bez logowania”, komentarze oraz raporty w „Moich materiałach” i ich eksport PDF. Nie potwierdzono tych opcji w pokazanym przez prowadzącego interfejsie kursów. Nie traktuj ich jako alternatywnej instrukcji dla obecnego kursu.</p><div class="grid-2">${figure('udostepnianie.png','Starszy ekran: grupa i kod',2,3,'Dokumentacja starszego interfejsu, nie bieżący ekran wyboru kursu.')}${figure('moje-materialy.jpg','Starszy ekran: Moje materiały',2,13,'Starsza lokalizacja raportów; obecny poradnik kursów prowadzi do zakładki Analiza.')}</div>${cite(2,13,'Starsze raporty — s. 13–18')}`)}
<p class="source-line">Zakres sprawdzenia: zrzut konta prowadzącego i publiczna pomoc ZPE, 3 listopada 2026. Nie wykonano próby kursu na zalogowanych kontach nauczyciela i ucznia.</p>`);

const users=chapter('uzytkownicy','07','Użytkownicy, grupy i odzyskiwanie dostępu','W poradniku kursów użytkownikami zarządza się przez Platforma → Uczniowie. Starsze PDF-y pokazują osobne moduły Klasy/Grupy.',`
<h3>Uczniowie i grupy w modelu kursów</h3><p>Na szkolnym koncie dane klas i uczniów są powiązane z SIO. Otwórz „Platforma → Uczniowie”, zaznacz potrzebne osoby i wybierz „Dodaj do grupy”. Publiczny poradnik opisuje też możliwość utworzenia grupy z zaznaczonych osób. Grupę zapisuje się do opublikowanego kursu przez zakładkę „Uczniowie” → „Zapisz uczniów” → „Grupy”.</p><p>Sprawdź skład grupy przed zapisem. Według instrukcji osoby dodane do grupy uzyskują dostęp do kursów, na które ta grupa jest zapisana.</p>${currentHelp('https://zpe.gov.pl/a/zapisywanie-uczniow/D2UOTPKJV','Uczniowie i grupy w kursach')}
<h3>Zmiana hasła lub adresu e-mail ucznia</h3>${steps([
 ['Otwórz listę uczniów','Wybierz „Platforma → Uczniowie”.'],
 ['Odszukaj konto','Przy właściwej osobie otwórz menu trzech kropek.'],
 ['Wybierz zmianę danych','Publiczna instrukcja pokazuje zmianę hasła oraz adresu e-mail. Użyj dostępnego formularza i jego obecnych wymagań. Nowe hasło przekaż indywidualnie.']
])}<p>Opis dotyczy kont uczniów, do których nauczyciel ma uprawnienia. Nie oznacza możliwości zmieniania dowolnych kont. Dla konta niewidocznego w Twojej strukturze skorzystaj z pomocy szkoły lub ZPE.</p>${currentHelp('https://zpe.gov.pl/a/zmiana-hasla-i-adresu-e-mail-uczniow/D2JLQ5G7Q','Zmiana danych uczniów')}
${detail('Starsze instrukcje: Klasy/Grupy, zaproszenia i link resetujący',`${olderProcedure}<p>PDF-y opisują „Utwórz grupę”, dodawanie przez e-mail, kolorowe statusy zaproszeń, ich ponawianie i menu „Akcje”. Poradnik użytkowników opisuje także wysłanie linku resetującego hasło. Dostępności tych opcji nie potwierdzono w obecnym modelu kursów. Nie należy mylić zaproszenia do starszej grupy z zapisem do kursu.</p><p>Edycja klas zaimportowanych z SIO jest w PDF-ach zablokowana. W przypadku rozbieżności danych sprawdź przypisanie w szkole.</p>${cite(5,1,'Starszy moduł użytkowników')}${cite(5,6,'Starsze opcje resetowania — s. 6–8')}${cite(6,1,'Starszy formularz grup')}${cite(7,10,'Starsze statusy i zaproszenia — s. 10–15')}`)}`);

const creatorItem=item=>detail(escapeHTML(item.title),`<p><strong>Co umożliwia:</strong> ${escapeHTML(item.what)}</p><p><strong>Przygotowanie według PDF-u:</strong> ${escapeHTML(item.setup)}</p><p><strong>Przykład zastosowania:</strong> ${escapeHTML(item.example)}</p>${cite(9,item.page,'Kreator e-materiałów')}`);
const creator=chapter('kreator','09','Kreator e-materiałów: możliwości i sposób pracy','Katalog możliwości z 67-stronicowego PDF-u oraz instrukcje obsługi z publicznego przewodnika WWW. Nie jest to potwierdzenie dostępności każdego komponentu na danym koncie. Rozwiń nazwę narzędzia, aby zobaczyć jego działanie, sposób przygotowania i przykład zastosowania.',`
<p>Kreator pozwala przygotować własny zasób z tekstem, multimediami i zadaniami. Możesz zacząć od pustego projektu lub opracować fragmenty zebrane w Teczce. Poniższe przykłady zastosowań są propozycjami do lekcji; opis obsługi pochodzi z poradnika.</p>
<div class="actions"><a class="button" href="#kreator-start">Pierwszy materiał</a><a class="button secondary" href="#kreator-cwiczenia">Rodzaje ćwiczeń</a><a class="button secondary" href="#kreator-dodatki">Gry, mapy i inne komponenty</a><button type="button" id="expand-creator">Rozwiń cały rozdział</button></div>
<div class="notice"><strong>Dwa źródła, różne ekrany.</strong> PDF Kreatora ma metadane z 2022 r. Nadal jest publikowany przez ZPE, ale obecny przewodnik WWW pokazuje inne sterowanie komponentami i dodatkowe pozycje. Szczegółowe opisy poniżej oznaczone „według PDF-u” zachowują jego zakres; nie potwierdzono ich wszystkich na zalogowanym koncie. ${external('https://zpe.gov.pl/kreator-przewodnik','Otwórz przewodnik WWW Kreatora')}</div>
<h3 class="subsection" id="kreator-start">1. Wejście do edycji i starsze ustawienia projektu</h3><p>Publiczny przewodnik WWW pokazuje kopiowanie gotowego materiału do Kreatora ikoną kartki z ołówkiem. W kursie edycję materiału otwiera się ikoną ołówka. Dalszy opis typów projektu i zakładek pochodzi ze starszego PDF-u — ich zgodności z obecnym kontem nie sprawdzono.</p>${currentHelp('https://zpe.gov.pl/a/wprowadzenie/DBQRCFQDH','Otwieranie i edycja materiału')}
${detail('Starszy PDF: typy projektu i spis treści',`${olderProcedure}<div class="split"><div>${steps([
 ['Otwórz Kreator','Zaloguj się do ZPE i przejdź do modułu „Kreator”. Otwiera się w nowym oknie. Na liście projektów zobaczysz rozpoczęte materiały.'],
 ['Wybierz typ','Kliknij „Dodaj”, wpisz nazwę i wybierz: jednostronicowy — bez spisu treści; wielostronicowy — ze spisem treści; „Lekcja” — z przygotowanymi komponentami; „Kartkówka” — z listą ćwiczeń interaktywnych.'],
 ['Uzupełnij ustawienia','Wpisz tytuł i opis, dodaj okładkę, wybierz przedmiot. Zapisz zieloną dyskietką. Poradnik pokazuje też podgląd wersji roboczej i autozapis.'],
 ['Ułóż spis treści','Prawym przyciskiem myszy na pozycji dodaj dokument nad lub pod nią. Rozdziały porządkują dokumenty i same nie zawierają treści. Przeciągaj dokumenty, aby zmienić kolejność; ikoną T zmieniaj nazwy. Zapisz strukturę.'],
 ['Przejdź do edycji','Kliknij tytuł dokumentu. W zakładce „Edycja” umieścisz tekst, multimedia i ćwiczenia.']
])}${cite(9,4,'Rozpoczęcie pracy — s. 4–8')}</div>${figure('kreator.png','Nawigacja dokumentu w Kreatorze',9,8,'Spis treści organizuje dokumenty wielostronicowego materiału.',true)}</div>`)}
<h3 class="subsection">2. Dodawanie i układanie treści</h3><p>W przewodniku WWW komponent wstawia się kliknięciem ikony przybornika lub przeciągnięciem. Kolejność zmienia się strzałkami albo przeciąganiem za zielone pole. Edycję otwiera ołówek, dwie kartki kopiują element, a czerwony znak × go usuwa. Starsza instrukcja przeciągania za kotwiczkę i usuwania przez upuszczenie na boczny panel nie opisuje tego samego ekranu.</p>${currentHelp('https://zpe.gov.pl/a/wprowadzenie/DBQRCFQDH','Obsługa komponentów w przewodniku WWW')}
<p>Opisy treści, multimediów i poszczególnych narzędzi poniżej zachowują nazwy ze źródłowego PDF-u.</p>
${window.CREATOR_REFERENCE.content.map(creatorItem).join('')}
<h3 class="subsection" id="kreator-cwiczenia">3. Ćwiczenia interaktywne: wspólne ustawienia</h3>
<p>Przewodnik WWW pokazuje ćwiczenia w trzeciej zakładce przybornika. Kliknij ikonę lub przeciągnij komponent, a potem otwórz edycję ołówkiem. Formularz zawiera treść, odpowiedzi i podgląd; osobne zakładki udostępniają edycję zaawansowaną, pomoc i opcje. W zakładce „Pomoc” każdego komponentu znajdziesz opis możliwości i przykładową treść.</p>
<p>Poradnik opisuje m.in. podpis, tekst alternatywny, pozytywną i negatywną informację zwrotną oraz opcje „Sprawdzenie odpowiedzi” i „Uruchom w trybie pełnoekranowym”. Ustaw je odpowiednio do zadania. Samo dodanie komponentu nie oznacza, że ma on automatyczne ocenianie — tablica interaktywna i pytania otwarte wymagają innego sposobu sprawdzenia.</p>${currentHelp('https://zpe.gov.pl/a/cwiczenia/DCE5J3BAR','Edycja i opcje ćwiczeń')}
${window.CREATOR_REFERENCE.exercises.map(creatorItem).join('')}
<h3 class="subsection" id="kreator-dodatki">4. Gry, mapy i dodatkowe komponenty</h3>
<p>Poniższe pozycje pochodzą z PDF-u. Katalog WWW ma inny zakres, m.in. „Wirtualną wycieczkę”, „Formularz PDF” i „Bąbelki”; nie należy traktować PDF-u jako pełnej listy obecnego edytora. Przy części z nich PDF podaje tylko krótki opis, dlatego szczegółowych pól konfiguracji szukaj w zakładce „Pomoc” danego komponentu. Nie wszystkie działają jak test z jedną poprawną odpowiedzią.</p>
${window.CREATOR_REFERENCE.additional.map(creatorItem).join('')}
<h3 class="subsection">5. Uczeń tworzy zadania, nauczyciel łączy ćwiczenia</h3>
${detail('Kreator pytań testowych dla uczniów',`<p>Komponent pozwala uczniom układać pytania dla innych osób. Wybierz jego ikonę z panelu. W edytorze zaawansowanym znak <code>#</code> uruchamia ustawienia domyślne. Parametr <code>answers</code> określa początkową liczbę odpowiedzi, <code>multiple</code> — wybór jednokrotny lub wielokrotny, <code>lock</code> — możliwość dodawania i usuwania odpowiedzi, a <code>task</code> — ustalone polecenie. Wartości i przykład składni podaje zakładka „Pomoc”.</p><p><strong>Przykład:</strong> uczeń układa pytanie o kolejność czynności zawodowych, a partner sprawdza, czy wskazana odpowiedź jest poprawna.</p>${cite(9,53,'Tworzenie ćwiczeń przez uczniów — s. 53–54')}`)}
${detail('Blok Test — kilka ćwiczeń w jednym miejscu',`<p>Przeciągnij komponent „Test” do dokumentu. Do niebieskiego pola dodaj nowe ćwiczenia lub przenieś już utworzone. Edytuj każde z nich i sprawdź cały zestaw w podglądzie. To komponent Kreatora; osobny moduł testów w funkcjonalnościach zaawansowanych jest opisany w innym poradniku.</p>${cite(9,54,'Testy i gry edukacyjne — s. 54–55')}`)}
<h3 class="subsection">6. Edycja zaawansowana</h3>
<p>Ikona <code>&lt;&gt;</code> przełącza dokument na edycję za pomocą znaczników. Treść widoku wizualnego jest odwzorowana w pseudokodzie; zgodnie z poradnikiem można przełączać tryby bez utraty treści. Nie trzeba znać tego sposobu edycji, aby zacząć od prostego materiału.</p>
${detail('Tabele HTML, kolumny i sekcje dla nauczyciela',`<ul><li><strong>Tabele:</strong> w widoku zaawansowanym wstaw kod tabeli HTML wewnątrz znaczników <code>&lt;table&gt;</code> i <code>&lt;/table&gt;</code>.</li><li><strong>Sekcje tylko dla nauczyciela:</strong> poradnik pokazuje znaczniki wydzielające treść dla nauczyciela od treści dla ucznia. Można w ten sposób umieścić wskazówki do prowadzenia zadania. Dokładny zapis skopiuj ze źródła i sprawdź widok ucznia.</li><li><strong>Kolumny:</strong> znaczniki kolumn określają proporcje podziału szerokości. Przydają się np. do zestawienia tekstu i ilustracji.</li></ul>${cite(9,55,'Tryby edycji i tabele — s. 55–56')}${cite(9,57,'Treść dla nauczyciela i kolumny')}`)}
${detail('Odnośniki tekstowe i kafle do innych e-materiałów',`<p>Odnośnik tekstowy wykorzystuje podpis i identyfikator projektu. Kafle automatycznie pobierają tytuł i okładkę wskazanego materiału. Parametry siatki wyznaczają liczbę kolumn i ich proporcje. Użyj wzorów ze stron 58–59 i podstaw identyfikatory swoich materiałów.</p><p><strong>Przykład:</strong> na końcu lekcji umieść kafle „Powtórzenie”, „Ćwiczenie” i „Dla chętnych”.</p>${cite(9,58,'Odnośniki i kafle — s. 58–59')}`)}
<h3 class="subsection">7. Dostępność materiału</h3>
${detail('Opisy alternatywne, alternatywne filmy i ćwiczenia',`<ul><li><strong>Ilustracje:</strong> otwórz edycję ołówkiem i wpisz opis alternatywny. Powinien przekazywać informację istotną dla zadania.</li><li><strong>Obrazy wewnątrz ćwiczeń:</strong> uzupełniaj opisy w oknie edycji danego ćwiczenia.</li><li><strong>Wideo:</strong> w polu „Alternatywa WCAG” dodaj alternatywną wersję pliku, np. z tłumaczeniem na język migowy. Odbiorca wybiera wersję w odtwarzaczu.</li><li><strong>Alternatywne ćwiczenia:</strong> PDF nie zawiera osobnej procedury, ale przewodnik WWW opisuje komponent „Alternatywa WCAG”: do górnego białego pola przeciąga się zadanie oryginalne, a do niebieskiego jego alternatywę. Tryb dostępności pokazuje wersję alternatywną. Sam opis ilustracji nie tworzy alternatywnego zadania. ${external('https://zpe.gov.pl/a/alternatywa-wcag/DEJLBCB9V','Instrukcja Alternatywy WCAG')}</li></ul>${cite(9,60,'Opisy ilustracji — s. 60–61')}${cite(9,62,'Alternatywne multimedia i opisy w ćwiczeniach — s. 62–63')}`)}
<h3 class="subsection">8. Starsze materiały edukacji wczesnoszkolnej</h3>
${detail('Zgrzyciaki — ograniczona edycja starszych zasobów',`<p>Poradnik osobno opisuje starsze materiały dla pierwszych klas szkoły podstawowej. Można w nich zmieniać tekst, ilustracje, nagrania, awatary i paczki widżetów, a także kolejność ekranów. Edycję otwiera się z projektu przez zakładkę „Edycja”; dostępne są również „Kod” i „Pliki”. To odrębny tryb, z ograniczeniami względem pozostałych e-materiałów.</p>${cite(9,64,'Starszy Kreator — s. 64–67')}`)}
<div class="example"><h3>Na początek: jeden własny materiał</h3><p>Utwórz projekt jednostronicowy, wpisz temat i krótkie polecenie, dodaj jedną ilustrację lub film i jedno ćwiczenie. Uzupełnij źródło i opis alternatywny, zapisz i sprawdź podgląd. Następnie dodaj materiał do kursu, opublikuj go i zapisz uczniów. Pozostałe komponenty dobieraj wtedy, kiedy pomagają osiągnąć cel zadania.</p><a href="#udostepnianie">Jak udostępnić materiał i odnaleźć odpowiedzi →</a></div>`);

const knowledge=chapter('baza','06','Co jeszcze można zrobić w ZPE?','To część do samodzielnego powrotu. Każdy temat ma zastosowanie, procedurę opisaną w źródle i bezpośrednie przejście do odpowiedniego poradnika.',`
${detail('Generator Kart Pracy — od prostej karty do pliku',`${currentHelp('https://zpe.gov.pl/a/generator-kart-pracy/D9D7YmwXP','Możliwości Generatora Kart Pracy')}<p>Publiczna pomoc potwierdza pracę bez konta i wydruk oraz zapis i udostępnianie po zalogowaniu. Poniższe szczegóły ekranów pochodzą z PDF-u.</p><div class="split"><div><span class="tag">Gdy potrzebujesz wydruku</span><h3>Tekst, grafika i własny układ strony</h3><p>Generator to osobne narzędzie do kart pracy. Instrukcja pokazuje zakładki: „Twoje karty pracy”, „Udostępnione dla mnie”, „Szablony karty pracy” i „Utwórz nową kartę pracy”.</p>${steps([['Nowa karta','W formularzu wymagany jest tytuł. Opis, klasa i przedmiot pomagają później porządkować zasoby.'],['Zawartość','W edytorze są biblioteki tekstu i grafiki, strony oraz warstwy. Można dodawać strony i zmieniać ich kolejność.'],['Zapis i podgląd','Zapisz kartę, obejrzyj układ i dopiero wtedy pobierz lub udostępnij gotowy materiał.']])}<p><strong>Kiedy warto:</strong> masz własne polecenie i potrzebujesz czytelnego układu do pracy na papierze. Kartę można utworzyć z szablonu lub od zera i wydrukować także bez logowania; zapis i udostępnienie wymagają konta.</p>${cite(3,1,'Praca bez logowania')}${cite(3,3,'Tworzenie karty — s. 3–5')}${cite(3,20,'Pobieranie karty')}</div>${figure('karta-pracy.png','Formularz nowej karty pracy',3,4,'Przykładowy tytuł, opis, klasa i przedmiot z oryginalnej instrukcji.',true)}</div>`)}
<div class="tile"><h3>Kreator e-materiałów</h3><p>Osobny rozdział opisuje cały zakres przekazanego poradnika: od nowego projektu po ćwiczenia, gry, opcje zaawansowane i dostępność.</p><a href="#kreator">Przejdź do pełnego przewodnika po Kreatorze →</a></div>
${detail('Ścieżki nauki — materiały w ustalonej kolejności',`${olderProcedure}<div class="split"><div><span class="tag">Sekwencja zasobów</span><h3>Nie tylko lista linków</h3><p>Ścieżka porządkuje materiały i warunki przechodzenia dalej. Instrukcja pozwala dodawać gotowe zasoby ZPE oraz własne materiały.</p>${steps([['Utworzenie','W „Moich materiałach” wybierz utworzenie ścieżki i dodaj materiał.'],['Kolejne kroki','Ustaw warunek zaliczenia, np. przeczytanie 80% materiału, i dodaj kolejny krok. Można wybrać, kiedy się pojawi, np. po tygodniu.'],['Udostępnienie','Zapisz ścieżkę i udostępnij ją. Sprawdź, czy odbiorca widzi kolejne kroki zgodnie z zamiarem.']])}<p><strong>Ważne:</strong> przeczytanie określonej części zasobu nie dowodzi opanowania umiejętności. Do oceny zrozumienia potrzebna jest odpowiedź lub wykonanie działania.</p>${cite(4,1,'Tworzenie i dodawanie materiałów — s. 1–4')}${cite(4,7,'Wyniki ścieżki')}</div>${figure('sciezka.jpg','Wybór materiału do ścieżki',4,2,'W oknie widoczne są własne materiały, Ulubione i katalog wszystkich materiałów.')}</div>`)}
${detail('Klasy i grupy — kto otrzyma materiał?',`${olderProcedure}<p>Klasy importowane z SIO i samodzielnie utworzone grupy mają inne zasady zarządzania. Instrukcje podkreślają, że klas zaimportowanych nie edytuje się tak jak własnych grup.</p><div class="grid-2"><div><h4>Własna grupa</h4><p>Utwórz grupę, nadaj jej nazwę, dodaj uczestników. Rozszerzony poradnik opisuje zaproszenia, ich ponowne wysłanie, dodawanie osób z istniejących klas i opuszczanie grupy.</p></div><div><h4>Grupa istnieje, ale brak dostępu</h4><p>Sprawdź użyte konto, uczestnictwo i status zaproszenia. Nie zakładaj, że wysłanie zaproszenia oznacza jego przyjęcie.</p></div></div>${cite(7,2,'Tworzenie grupy')}${cite(7,13,'Zaproszenia')}${cite(5,1,'Użytkownicy i klasy z SIO')}${cite(6,1,'Krótka instrukcja grup')}`)}
${detail('Komunikator i Wiadomości — dwa narzędzia komunikacji',`${olderProcedure}<div class="grid-2"><div><h4>Komunikator</h4><p>Poradnik opisuje kanały publiczne, grupy prywatne i wiadomości bezpośrednie. Dostępne są m.in. wzmianki, załączniki i wyszukiwanie wiadomości. Zakres widoczności trzeba dobrać do odbiorców.</p>${source(1,2,'Ekran i nawigacja')}${cite(1,6,'Wysyłanie wiadomości')}</div><div><h4>Moduł Wiadomości</h4><p>Osobna instrukcja prowadzi przez funkcjonalności zaawansowane do wiadomości odebranych i wysłanych. Opisuje wyszukiwanie oraz wybór odbiorcy: osoby, grupy lub klasy.</p>${source(8,1,'Moduł Wiadomości')}</div></div><div class="tip"><strong>Czytelna wiadomość do uczniów:</strong> nazwa materiału, dokładny fragment, czynność do wykonania i sposób przekazania odpowiedzi.</div>`)}
${detail('Testy, ankiety, pliki i inne funkcje zaawansowane',`${olderProcedure}<p>Instrukcja zarządzania materiałami obejmuje testy, ankiety, kursy, filmy, pliki PDF, inne pliki, linki oraz paczki SCORM. Dla poszczególnych obiektów dostępne są różne ustawienia, wyniki i statystyki.</p><div class="grid-2"><div><h4>Test</h4><p>Najpierw zapisuje się obiekt i parametry. Następnie dodaje pytania. Trzeba sprawdzić próg zaliczenia, sposób prezentowania odpowiedzi i zachowanie kolejnych podejść.</p></div><div><h4>Ankieta</h4><p>Służy zbieraniu odpowiedzi, a nie temu samemu rozstrzygnięciu co test wiedzy. Poradnik opisuje również pytania ze skalą.</p></div></div><p>Moduł działa w „Funkcjonalnościach zaawansowanych”. Na początek wystarczą gotowe ćwiczenia z e-materiałów.</p>${cite(10,1,'Mapa obiektów i funkcji')}${cite(10,13,'Dodawanie testu')}`)}
<p class="source-line">Dla obecnego kursu kolejność i warunki przejść opisuje pomoc „Etapy kursu”. ${external('https://zpe.gov.pl/a/etapy-kursu/D8BVAQD3N','Etapy kursu')} Starszy moduł Ścieżki nauki nie jest tą samą instrukcją.</p>`);

const work=chapter('praca','07','Twój temat: od wyszukania do przypisania','W pracowniach na trzecim piętrze każdy pracuje nad wybranym przez siebie tematem lekcji. Odnajduje materiał w ZPE, przygotowuje go i przypisuje swoim uczniom. Prowadzący pomaga na każdym etapie.',`
<div class="work-area"><span class="tag">Praca nad własnym tematem</span><h3>Odnajdź, przygotuj, przypisz</h3><p>Efektem jest materiał przypisany uczniom na Twoim koncie ZPE, gotowy do użycia na lekcji.</p><div class="grid-3"><div class="tile"><h3>1. Odnajdź</h3><p>Zacznij od pojęcia, etapu i przedmiotu. W zawodzie użyj działu „Kształcenie zawodowe”, nazwy czynności albo symbolu kwalifikacji. Oceń wynik według tabeli w rozdziale „Wybór i zapis”.</p></div><div class="tile"><h3>2. Przygotuj</h3><p>Wybierz fragment, z którym będą pracować uczniowie. Kilka fragmentów połącz w Teczce. Sprawdź ustawienie pokazywania prawidłowych odpowiedzi w kursie.</p></div><div class="tile"><h3>3. Przypisz</h3><p>Dodaj materiał do nowego lub istniejącego kursu, opublikuj go i zapisz uczniów. Wyników szukaj w kursie, w zakładce „Analiza”.</p></div></div><div class="actions">${external('https://zpe.gov.pl/','Przejdź do ZPE','button')}<a class="button secondary" href="#szukanie">Wróć do instrukcji szukania</a></div></div>`);

const resourceCard=r=>`<article class="tile resource-card"><p class="subject">${escapeHTML(r.subject)}</p><h3>${escapeHTML(r.title)}</h3><p><strong>Co otworzyć:</strong> ${escapeHTML(r.fragment)}</p>${external(r.url,'Otwórz zasób ZPE')}${r.extra?' '+external(r.extra[1],r.extra[0]):''}${detail('Wskazówka do wykorzystania',`<p>${escapeHTML(r.note)}</p><p><strong>Zadanie dla ucznia:</strong> ${escapeHTML(r.task)}</p><p><strong>Co sprawdzić:</strong> ${escapeHTML(r.evidence)}</p>`)}</article>`;
const library=chapter('biblioteka','08','Materiały, które zostają po spotkaniu','Przykładowe zasoby, ilustrowany przewodnik i pełne instrukcje. Każdy dokument otwiera się osobno.',`
<div class="grid-2"><article class="tile"><span class="tag">Do pobrania</span><h3>Pełny przewodnik PDF</h3><p>Pełne rozdziały, rozwinięcia, przykłady i ilustracje. Z okładką, spisem treści i informacją o projekcie.</p><div class="actions">${external('output/pdf/przewodnik-zpe-ilustrowany.pdf','Pobierz przewodnik','button')}<button type="button" id="print-guide">Drukuj stronę</button></div></article><article class="tile"><span class="tag">Cały pakiet</span><h3>Materiały w jednym archiwum</h3><p>Strona, ilustracje, PDF-y i oryginalne poradniki. Po rozpakowaniu zachowaj strukturę folderów.</p><div class="actions">${external('output/zpe-bez-pospiechu.zip','Pobierz ZIP','button secondary')}</div></article></div>
<h3 class="subsection">Przedmioty ogólnokształcące: przykładowe zasoby</h3><p>Propozycje do wykorzystania i punkt wyjścia do własnych poszukiwań.</p>
<div class="grid-2">${DATA.resources.filter(r=>r.kind==='ogólne').map(resourceCard).join('')}</div>
<h3 class="subsection">Fryzjer, handlowiec, cukiernik, kucharz: przykładowe zasoby</h3><p>E-materiały z działu kształcenia zawodowego. Zadania do nich są w rozdziale „Uczniowie pracują”.</p><div class="grid-2">${DATA.resources.filter(r=>r.kind==='zawodowe').map(resourceCard).join('')}</div>
<h3 class="subsection">11 oryginalnych poradników ZPE — zakres aktualności</h3><p>Oryginalne pliki zachowano bez zmian. Większość ma metadane utworzenia z 2022 r., Generator Kart Pracy z 2023 r. Data pliku nie potwierdza aktualności treści; także PDF zapisany w 2026 r. zawiera starsze ścieżki. Przy każdym dokumencie podano ograniczenie jego użycia.</p><div class="library-grid">${DATA.pdf_guides.map((g,i)=>`<a class="pdf-card" href="${escapeHTML(g.file)}" target="_blank" rel="noopener"><span class="pdf-badge">PDF</span><span><strong>${escapeHTML(g.title)}</strong><small>${g.pages} stron · ${escapeHTML(g.topics.slice(0,2).join(', '))}</small><small class="source-status">${escapeHTML(SOURCE_STATUS[i])}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div>
${detail('Źródła ilustracji',`<p>Osiem grafik wyodrębniono z przekazanych PDF-ów, bez zmieniania przedstawionych ekranów. Przy ilustracjach są odsyłacze do odpowiednich stron. Ilustracja serca pochodzi z publicznej instrukcji Ulubione w ZPE.</p><p>Poradniki pokazują wersje interfejsu z czasu ich opracowania, część z nich na przykładach ze szkoły podstawowej.</p><p>Aktualizacja przewodnika: 3 listopada 2026.</p>`)}`);

document.getElementById('tresc').innerHTML=hero+introduction+trainingPlan+models+account+search+selection+users+sharing+creator+knowledge+work+library;

document.querySelectorAll('.chapter-number').forEach((node,i)=>node.textContent=String(i+1).padStart(2,'0'));

// Powiększanie oryginalnych ekranów bez ich modyfikowania.
const dialog=document.getElementById('image-dialog');
document.addEventListener('click',event=>{
 const zoom=event.target.closest('[data-zoom]');
 if(zoom){document.getElementById('dialog-image').src=zoom.dataset.zoom;document.getElementById('dialog-image').alt=zoom.dataset.title;document.getElementById('image-title').textContent=zoom.dataset.title;document.getElementById('image-caption').textContent=zoom.dataset.caption;dialog.showModal();}
});
document.getElementById('expand-creator').addEventListener('click',e=>{const items=[...document.querySelectorAll('#kreator details')];const open=items.some(d=>!d.open);items.forEach(d=>d.open=open);e.currentTarget.textContent=open?'Zwiń cały rozdział':'Rozwiń cały rozdział';});
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.getElementById('focus-toggle').addEventListener('click',e=>{const on=document.body.classList.toggle('leading');e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Widok przewodnika':'Tryb prowadzenia';});
document.getElementById('print-guide').addEventListener('click',()=>{const closed=[...document.querySelectorAll('details:not([open])')];closed.forEach(d=>d.open=true);window.addEventListener('afterprint',()=>closed.forEach(d=>d.open=false),{once:true});window.print();});

// Stare odsyłacze zachowują sens po przejściu ze slajdów do rozdziałów.
function resolveOldRoute(){
 const hash=location.hash;
 const aliases={'/centrum-materialow':'biblioteka','/poradniki':'biblioteka','/materialy':'biblioteka','/baza-wiedzy':'baza','/wstep':'wprowadzenie','/pokaz':'udostepnianie','/zrodla':'biblioteka','/karty':'szukanie','/trener':'modele','/moja-lekcja':'praca','/sprawdzenie':'praca','/druk-planu':'praca'};
 if(!hash.startsWith('#/'))return;
 let key=hash.slice(1),id=aliases[key];
 if(key.startsWith('/baza-wiedzy/'))id='baza';
 if(key.startsWith('/s/')){const n=Number(key.slice(3));id=n<=2?'start':n<=5?'modele':n===6?'konto':n<=9?'szukanie':n<=14?'wybor':n===15?'udostepnianie':n===16?'baza':n===17?'praca':'biblioteka';}
 if(key.startsWith('/etap/'))id='szukanie';
 if(id){history.replaceState(null,'','#'+id);document.getElementById(id)?.scrollIntoView();}
}
window.addEventListener('hashchange',resolveOldRoute);resolveOldRoute();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){document.querySelectorAll('#chapter-nav a').forEach(a=>{if(a.hash==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}},{rootMargin:'-100px 0px -65% 0px',threshold:0});document.querySelectorAll('.chapter').forEach(s=>observer.observe(s));}
